110	
111	    std::vector<int> idx;
112	    for(int i=0; i < int(modes.size()); i++)
113	    {
114	       idx.push_back(i);
115	    }
116	
117	    auto left = std::find(idx.begin(), idx.end(), getCurrentIndex()-1);
118	    auto right = std::find(idx.begin(), idx.end(), getCurrentIndex()+1);
119	    auto foundLeft = false;
120	    auto foundRight = false;
121	
122	    if ( left != idx.end() )
123	    {
124	       foundLeft = true;
125	    }
126	
127	    if ( right != idx.end() )
128	    {
129	       foundRight = true;
130	    }
131	
132	    auto lastIndex = getCurrentIndex();
133	
134	    if (int(modes.size()) > 0) {
135	        if (getCurrentIndex() == index)
136	        {
137	            if (foundLeft)
138	            {
139	                setCurrentIndex(getCurrentIndex()-1);
140	            }
141	            else if (foundRight)
142	            {
143	                 setCurrentIndex(getCurrentIndex()+1);
144	            }
145	        }
146	    }
147	
148	    if (getActiveMode() == modes.at(index)) {
149	         deactivate(getActiveMode());
150	    }
151	
152	    delete modes.at(index);
153	    modes.erase(modes.begin() + index);
154	
155	    if (getCurrentIndex() == 1 && lastIndex == 0) {
156	        setCurrentIndex(0);
157	    }
158	
159	    emit ModeClosed(index);
